# v626: Premium tiers with exclusive planet skins and stacking buffs. See p626_prem.js.
import sys, re
P = sys.argv[1] if len(sys.argv) > 1 else 'docs/index.html'
s = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:90]); s = s.replace(a, b)
js = open('tools/patches/p626_prem.js', encoding='utf-8').read()
css = ('.prtile{border-color:rgba(255,210,90,.6)!important;background:radial-gradient(90% 80% at 85% 15%,rgba(255,210,90,.3),transparent 65%),linear-gradient(160deg,#2a2010,#120c06)!important}.prtile .ctic{font-size:28px;line-height:34px;color:#ffd25a}'
  '.prcrest{position:relative;display:inline-grid;place-items:center;width:var(--s);height:var(--s);margin-left:6px;vertical-align:middle;clip-path:polygon(50% 0,100% 22%,100% 70%,50% 100%,0 70%,0 22%);background:linear-gradient(160deg,#fff6d0,var(--c) 45%,color-mix(in srgb,var(--c) 40%,#000));filter:drop-shadow(0 0 6px var(--c))}.prcrest b{font:800 calc(var(--s)*.45)/1 var(--f-display);color:#1a1006}.prgold{color:#ffd25a!important;text-shadow:0 0 10px rgba(255,210,90,.6)}'
  '.prprog{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:4px;margin:4px 0}.prprog button{aspect-ratio:1;border-radius:8px;border:1px solid color-mix(in srgb,var(--c) 40%,transparent);background:rgba(10,14,22,.7);color:var(--muted);font:700 12px var(--f-display);cursor:pointer;padding:0}.prprog button.on{background:color-mix(in srgb,var(--c) 30%,#0a0e16);color:#fff;box-shadow:0 0 8px color-mix(in srgb,var(--c) 60%,transparent)}.prprog button.sel{outline:2px solid var(--c);outline-offset:1px}'
  '.prcard,.prprog,.prchest,.prhow{flex-shrink:0}.prcard{position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:center;gap:8px;padding:14px 12px;margin-top:8px;border-radius:18px;border:1px solid color-mix(in srgb,var(--c) 50%,transparent);background:radial-gradient(70% 50% at 50% 22%,color-mix(in srgb,var(--c) 26%,transparent),transparent 70%),linear-gradient(180deg,#0d1220,#070a12)}'
  '.prsk{position:relative;width:170px;height:170px}.prsk canvas{width:100%;height:100%}.prring{position:absolute;inset:-6px;border-radius:50%;border:2px solid color-mix(in srgb,var(--c) 60%,transparent);box-shadow:0 0 28px color-mix(in srgb,var(--c) 45%,transparent);animation:fgspin 16s linear infinite;pointer-events:none}.prcard:not(.own) .prsk canvas{filter:saturate(.35) brightness(.7)}'
  '.prct{display:flex;flex-direction:column;align-items:center;text-align:center;gap:3px}.prct small{letter-spacing:.2em;color:var(--c);font-size:11px}.prct b{font:800 21px var(--f-display);color:#fff;text-shadow:0 0 12px color-mix(in srgb,var(--c) 70%,transparent)}.prct em{font-style:normal;font-size:12px;color:var(--muted)}.prperk{font-size:12px;color:#8affb4}'
  '.prbuffs{width:100%;display:flex;flex-direction:column;gap:4px;padding:8px 10px;border-radius:12px;background:rgba(255,255,255,.04)}.prbuffs span{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#e2cf94}.prbuffs i{font-style:normal;font-size:13px;padding-left:16px;position:relative}.prbuffs i::before{content:"◆";position:absolute;left:0;color:var(--c);font-size:10px;top:2px}.prbuffs i.nw{color:#fff}.prbuffs i.nw::after{content:" NEW";color:var(--c);font-size:10px;font-weight:700}'
  '.prst{width:100%}.prlock{display:block;text-align:center;color:var(--muted);font-size:13px;padding:8px}.prchest{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:10px;padding:10px 12px;border-radius:12px;border:1px solid rgba(255,210,90,.4);background:rgba(255,210,90,.07)}.prchest span{color:#ffd25a;font-weight:700;font-size:13px}.prhow{margin-top:10px}.prhow b{font-size:13px}\n')
i = s.index('</style>', s.index('#celeb{position:fixed')); s = s[:i] + css + s[i:]
a = s.index('const PXC = {}; // id'); s = s[:a] + js + '\n' + s[a:]
rep('const pxOwned = k => !!(FREE_SKINS || ownerFree() || (S && S.pxOwn || {})[k]);', 'const pxOwned = k => PXS[k] && PXS[k].prem ? !!(ownerFree() || premT() >= PXS[k].prem) : !!(FREE_SKINS || ownerFree() || (S && S.pxOwn || {})[k]); /* v626 premium skins come only with the tier */')
rep('im.src = PX_DIR + src + (PX_FIX[src] ? "?v=" + PX_FIX[src] : ""); }', 'src = src.replace(/^([a-z0-9]+)(-map)?\\.webp$/, (m, a, b) => (PXS[a] && PXS[a].alias ? PXS[a].alias : a) + (b || "") + ".webp"); /* v626 a premium skin shows its stand-in painting until its own art arrives */ im.src = PX_DIR + src + (PX_FIX[src] ? "?v=" + PX_FIX[src] : ""); }')
rep(': `<button class="btn amber sm" data-act="pxBuy" data-k="${k}" ${(S.shards || 0) >= s.cost ? "" : "disabled"}>', ': s.prem ? `<button class="btn ghost sm" data-act="premOpen">🔒 Premium Tier ${s.prem}</button>` : `<button class="btn amber sm" data-act="pxBuy" data-k="${k}" ${(S.shards || 0) >= s.cost ? "" : "disabled"}>')
rep('pxBuy: d => act(() => { const s = PXS[d.k]; if (!s) return;', 'pxBuy: d => act(() => { const s = PXS[d.k]; if (!s) return; if (s.prem) return toast(`${s.n} comes with Premium Tier ${s.prem}.`, "warn");')
rep('const vipEff = () => vipStats(vipOn() ? vipLvl() : 0);', 'const vipEff = () => premAdd(vipStats(vipOn() ? vipLvl() : 0)); /* v626 premium buffs ride along */')
rep('const fsQMax = L => clamp(1 + Math.floor((L == null ? fsDockL() : L) / 4), 1, FS_QMAX);', 'const fsQMax = L => clamp(1 + Math.floor((L == null ? fsDockL() : L) / 4), 1, FS_QMAX) + (premB().fq || 0);')
rep('const fsForgeK = L => 1 - Math.min(.3, .03 * Math.max(0, (L == null ? fsDockL() : L) - 1));', 'const fsForgeK = L => (1 - Math.min(.3, .03 * Math.max(0, (L == null ? fsDockL() : L) - 1))) * (1 - (premB().forge || 0));')
rep('function pkApply(c, sign) { const got = [];', 'function pkApply(c, sign) { const got = []; if (c.premT) { if (sign > 0) S.premT = Math.max(S.premT || 0, c.premT); else if ((S.premT || 0) <= c.premT) S.premT = c.premT - 1; got.push(`Premium Tier ${c.premT}`); } /* v626 */')
rep('if (!S.grants[g.id]) { const got = pkApply(g.contents || {}, 1);', 'if (!S.grants[g.id]) { if (g.source === "purchase" && P && +P.priceUsd > 0) S.premUsd = +((S.premUsd || 0) + +P.priceUsd).toFixed(2); /* v626 lifetime support */ const got = pkApply(g.contents || {}, 1);')
rep('if (!S.grantsRev[g.id]) { pkApply(g.contents || {}, -1);', 'if (!S.grantsRev[g.id]) { if (g.source === "purchase" && P && +P.priceUsd > 0) S.premUsd = Math.max(0, +((S.premUsd || 0) - +P.priceUsd).toFixed(2)); pkApply(g.contents || {}, -1);')
rep('<div class="cmdid"><b>${esc(name)}</b>', '<div class="cmdid"><b class="${premB().gold ? "prgold" : ""}">${esc(name)}${premCrest(premT(), 22)}</b>')
rep('${tl("settings", ic(MI.grid), "Save, sound and account")}', '<button class="ctile prtile" style="--c:#ffd25a" data-act="premOpen"><span class="ctic">${premT() ? premCrest(premT(), 34) : "♛"}</span>${premChestReady() ? \'<span class="ctbad">!</span>\' : ""}<b>Premium</b><small>${premT() ? `Tier ${premT()} · ${esc(PREM[premT()].n)}` : "Ten tiers, exclusive skins"}</small></button>${tl("settings", ic(MI.grid), "Save, sound and account")}')
rep('archives: shArch, depot: shDepot, inv: shInv,', 'archives: shArch, depot: shDepot, inv: shInv, premium: shPrem,')
rep('  cmdPage: d => {', '  premOpen: () => { closeSheet(); openSheet({ type: "premium", noIntro: 1 }); }, premSel: d => { G.premSel = +d.t; renderSheet(); },\n'
    '  premChest: () => act(() => { if (!premChestReady()) return toast("Already claimed today.", "warn"); const n = premB().chest; S.premChest = utcDay(); grantRw({ m: 0, c: 0, g: 0, shards: n }, `Premium Tier ${premT()} daily chest`); toast(`Premium chest: +◆${n}.`, "win"); try { SFX.research(); } catch (e) {} if (sheet) renderSheet(); }), /* v626 */\n  cmdPage: d => {')
s2 = re.sub(r"GAME_V = 625\b", "GAME_V = 626", s); assert s2 != s; s = s2
open(P, 'w', encoding='utf-8').write(s); print('ok')
